/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG PAL calculation (no CCR)
/// </summary>
class METTMSShipmentItemGroupUOM_PAL extends METTMSShipmentItemGroupUOM
{    
}

Method.Source:
/// <summary>
/// Method for the TSIG quantity UOM
/// </summary>
/// <returns>Shipment UOM PAL</returns>
METShipmentUOM shipmentUOM()
{
    return METConstants::unitPAL;
}

/// <summary>
/// For PAL, the order _tmsShipmentItemGroup fields are calculated is a bit different first Cube, second Quantity and third Weight
/// as opposed to first Quantity, second Weight and third Cube
/// </summary>
/// <param name = "_tmsShipmentItemGroup"><c>METTMSShipmentItemGroup</c> to initialise fields</param>
void calcOrder(METTMSShipmentItemGroup _tmsShipmentItemGroup)
{
    // calcule cube first then quantity
    _tmsShipmentItemGroup.Cube = this.cube(_tmsShipmentItemGroup.Quantity);
    _tmsShipmentItemGroup.Quantity = this.quantity(_tmsShipmentItemGroup.Cube);
    _tmsShipmentItemGroup.Weight = this.weight(_tmsShipmentItemGroup.Quantity);        
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    METQty ret;
    //METWHSPalletVolume  whsToteVolume; // TODO
    //METWHSPalletVolume  whsCaseVolume; // TODO

    if (isKegItem)
    {
        ret = lineTmpSum.LineVolume_Kegs;
    }
    else
    {
        ret = isToteCustomer ? (lineTmpSum.LineVolume_CaseLines + whsToteVolume * repackContainersByCommodity)
                             : (lineTmpSum.LineVolume_CaseLines + whsCaseVolume * repackContainersByCommodity);
    }

    return ret;
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <param name = "_cube">TSIG volume (cube)</param>
/// <returns>TSIG quantity</returns>
METQty quantity(METWHSPalletVolume _cube = 0)
{
    METQty ret;

    if (isKegItem)
    {
        ret = inventParameters.METKegsPerPallet ? decRound(lineTmpSum.SalesQty / inventParameters.METKegsPerPallet, 2) : 0;
    }
    else
    {
        // TODO the whsPalletVolume is coming from the ShippingWhs which could be different at the SO line level
        // Needs to split the tmsShipmentItemGroup.Cube sum per WH, get the WH palletVolume and sum everything :o
        //METWHSPalletVolume whsPalletVolume;
        ret = whsPalletVolume ? _cube/whsPalletVolume : 0;
    }

    if (ret < 0.01)
    {
        ret = 0.01;
    }

    return ret;
}

/// <summary>
/// Method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METWHSPalletWeight weight(METQty _quantity)
{
    METQty ret;
    //METWHSPalletWeight  whsPalletWeight; // TODO
    //METWHSPalletWeight  whsToteWeight; // TODO

    if (isKegItem)
    {
        ret = lineTmpSum.LineWeight_Kegs + decRound(_quantity, 0) * whsPalletWeight;
    }
    else
    {
        if (isToteCustomer)
        {
            ret = this.weightCalc(_quantity) + whsToteWeight * repackContainersByCommodity;
        }
        else
        {
            ret = this.weightCalc(_quantity);
        }
    }

    return ret;
}

/// <summary>
/// Main method to calculate TSIG weight for non Keg item
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METWHSPalletWeight weightCalc(METQty _quantity)
{
    //METWHSPalletWeight  whsPalletWeight; // TODO

    return lineTmpSum.LineWeight_CaseLines
         + lineTmpSum.LineWeight_BrokenCaseSecurity
         + lineTmpSum.LineWeight_BrokenCaseNonSecurity
         + decRound(_quantity, 0) * whsPalletWeight;
}
